/** 
 * Parses a line of an OS2 FTP server file listing and converts it into a usable format in the form of an <code> FTPFile </code> instance.  If the file listing line doesn't describe a file, <code> null </code> is returned, otherwise a <code> FTPFile </code> instance representing the files in the directory is returned. <p/>
 * @param entry A line of text from the file listing
 * @return An FTPFile instance corresponding to the supplied entry
 */
public Path parseFTPEntry(Path parent,String entry){
  Path f = null;
  try {
    f = PathFactory.createPath(parent.getSession());
    if (matches(entry)) {
      String size = group(1);
      String attrib = group(2);
      String dirString = group(3);
      String mo = group(4);
      String da = group(5);
      String yr = group(6);
      String hr = group(7);
      String min = group(8);
      String name = group(9);
      if (null == name || name.equals("") || name.equals(".") || name.equals("..")) {
        return null;
      }
      if (dirString.trim().equals("DIR") || attrib.trim().equals("DIR")) {
        f.attributes.setType(Path.DIRECTORY_TYPE);
      } else {
        f.attributes.setType(Path.FILE_TYPE);
      }
      Calendar cal = Calendar.getInstance();
      int month = new Integer(mo).intValue() - 1;
      int day = new Integer(da).intValue();
      int year = new Integer(yr).intValue() + 2000;
      int hour = new Integer(hr).intValue();
      int minutes = new Integer(min).intValue();
      if (year > 2080) {
        year -= 100;
      }
      cal.set(Calendar.SECOND, 0);
      cal.set(Calendar.MINUTE, minutes);
      cal.set(Calendar.HOUR_OF_DAY, hour);
      cal.set(Calendar.YEAR, year);
      cal.set(Calendar.DATE, day);
      cal.set(Calendar.MONTH, month);
      f.attributes.setTimestamp(cal.getTime());
      f.setPath(parent.getAbsolute(), name.trim());
      Long theSize = new Long(size.trim());
      theSize = new Long(String.valueOf(theSize.intValue()));
      f.status.setSize(theSize.longValue());
      return (f);
    }
    return null;
  } catch (ClassCastException | NullPointerException | IndexOutOfBoundsException e) {
    // Log the exception and return null to indicate failure
    System.err.println("Error processing FTP entry: " + e.getMessage());
    return null;
  }
}
